/* eslint-disable @next/next/no-img-element */
/**
 * Official MEKI logo — the APPROVED marketing files (client edits, 23 Nov 2026): "MEKI" with "Misr El-Kheir International"
 * underneath, no ®. Green on light backgrounds, white on dark green (hero, Gala page, footer). Web copies are proportional
 * resizes generated by scripts/build-brand.mjs (provenance: public/brand/approved-logo-manifest.json). Never redraw or stretch:
 * only the width is set; the height follows the intrinsic 1200×365 ratio.
 */
export const LOGO_SRC = { green: "/brand/MEKI_Secondary_Green.png", white: "/brand/MEKI_Secondary_White.png" } as const;

export function Logo({ variant = "green", className = "", alt = "MEKI", brand }: { variant?: "green" | "white"; className?: string; alt?: string; brand?: { green?: string; white?: string } }) {
  // Site settings → Branding may name another approved file per variant (applySiteSettings validates it); default = approved artwork
  return <img src={brand?.[variant] ?? LOGO_SRC[variant]} alt={alt} width={1200} height={365} decoding="async" className={`h-auto w-[136px] max-w-none sm:w-[160px] ${className}`} />;
}
